function animate(env,el,p){
    function A(n){ var a=Math.abs(n); if(a>=1e9) return (n/1e9).toFixed(1).replace(/\.0$/,"")+"B"; if(a>=1e6) return (n/1e6).toFixed(1).replace(/\.0$/,"")+"M"; if(a>=1e3) return (n/1e3).toFixed(1).replace(/\.0$/,"")+"K"; return ""+n; }
    el.text=el.text.replace(/-?\d+(\.\d+)?/g, function(s){ return A(parseFloat(s)); }); return el;
}
